  chief_complaint = #{chiefComplaint}, symptoms = #{symptoms}, temperature_c = #{temperatureC},
  pulse_bpm = #{pulseBpm}, bp_systolic = #{bpSystolic}, bp_diastolic = #{bpDiastolic},
  weight_kg = #{weightKg}, diagnosis = #{diagnosis}, doctor_notes = #{doctorNotes},
  advice = #{advice}, follow_up_date = #{followUpDate}
WHERE id = #{id}
